python3 -c "
import json
with open('/app/resources/treasury_bulletin_1970_01.json', 'r') as f:
    data = json.load(f)

# Search for any CPI-related content
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, path + '.' + k)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search(v, path + f'[{i}]')
    else:
        if obj and isinstance(obj, str) and ('cpi' in obj.lower() or 'price' in obj.lower() or 'index' in obj.lower()):
            print(f'{path}: {obj}')

search(data)
"
